  "Aktier, kurser och budget – köp billigt, sälj dyrt och håll koll på kunderna.": "Hisseler, kurlar ve bütçe – ucuza al, pahalıya sat ve müşterileri takip et.",
  "Aktierna går upp i dag!": "Hisseler bugün yükseliyor!",
  "Ali": "Ali",
  "Alla": "Hepsi",
  "Alla TV-apparater visar samma film.": "Bütün televizyonlar aynı filmi gösteriyor.",
  "Alla blänker! Tjuven gillar bara saker som glittrar. Och den kan flyga …": "Hepsi parlıyor! Hırsız sadece parlak şeyleri seviyor. Ve uçabiliyor …",
  "Alla börjar i en rostig husvagn ute i förorten. Tjäna pengar på stadens jobb, köp mat så du orkar, klä dig snyggt – och spara ihop till en bättre bostad hos bostadsbyrån!": "Herkes banliyödeki paslı bir karavanda başlar. Şehirdeki işlerde para kazan, gücün kalsın diye yemek al, şık giyin – ve emlakçıdan daha iyi bir ev için para biriktir!",
  "Alla dagens djur är sålda – nya kommer i morgon!": "Bugünün hayvanlarının hepsi satıldı – yarın yenileri gelir!",
  "Alla dina djur har en annons.": "Bütün hayvanlarının ilanı var.",
  "Alla fyra livsmålen på <b>{0} dagar</b> – från en rostig husvagn till ett riktigt liv!": "Dört hayat hedefi de <b>{0} günde</b> – paslı bir karavandan gerçek bir hayata!",
  "Alla föreläsningar är klara – skriv tentan i biblioteket!": "Bütün dersler bitti – kütüphanede sınava gir!",
  "Alla i samma rad, tack!": "Hepimiz aynı sırada, lütfen!",
  "Alla jobb i Pixelstaden – närmast först. 🧭 Visa vägen så pekar en pil dit.": "Pixelkent'teki bütün işler – en yakın önce. 🧭 Yolu göster'e basınca bir ok oraya işaret eder.",
  "Alla kassor är upptagna – jag väntar en stund.": "Bütün gişeler dolu – biraz bekliyorum.",
  "Alla katterna här kommer från Tassarnas hem. Vill du adoptera? Fråga där!": "Buradaki tüm kediler Pati Yuvası'ndan. Sahiplenmek ister misin? Orada sor!",
  "Alla mår fint, tack.": "Herkes iyi, sağ ol.",
  "Alla nio portarna": "Dokuz kapının hepsi",
  "Alla stolar är upptagna – vänta en liten stund!": "Bütün koltuklar dolu – biraz bekle!",
  "Alla storlekar finns i kartongerna – från 20 till 46! 📦": "Kutularda her numara var – 20'den 46'ya! 📦",
  "Alla säger så.": "Herkes öyle der.",
