  "Ett barn har tappat bort sin mamma i lokalen. Vad gör du?": "Bir çocuk dükkânda annesini kaybetti. Ne yaparsın?",
  "Ett berg av räkor på en skiva bröd. Måsarna tittar avundsjukt.": "Bir dilim ekmeğin üstünde karides dağı. Martılar kıskançlıkla bakıyor.",
  "Ett blått hus med vita knutar. Katten Misse sover på verandan.": "Beyaz kenarlı mavi bir ev. Kedi Minnoş verandada uyuyor.",
  "Ett bo fullt av glitter? Och mina pärlor där? Haha, vilken skata!": "Parlak şeylerle dolu bir yuva mı? İncilerim de orada mı? Haha, ne saksağan ama!",
  "Ett brädspel för hela familjen – knuffa hem dina pjäser!": "Bütün aile için bir kutu oyunu – piyonlarını eve ulaştır!",
  "Ett byte! Skator vill ha något blankt i stället. Nova på BLING BLING har säkert något glittrigt …": "Takas! Saksağanlar karşılığında parlak bir şey ister. BLING BLING'deki Nova'da kesin parlak bir şey vardır …",
  "Ett dagskort kostar {0} och gäller hela dagen. Ett pass tar 10 energi.": "Günlük bilet {0} ve bütün gün geçerli. Bir antrenman 10 enerji alır.",
  "Ett djur som blir klappat och lekt med varje dag samarbetar bäst i ringen.": "Her gün sevilen ve oynanan bir hayvan ringde en uyumlu olandır.",
  "Ett djur som varit på hälsokoll den senaste veckan får extra poäng för hälsan på utställningen!": "Son bir hafta içinde sağlık kontrolünden geçen bir hayvan sergide ekstra sağlık puanı alır!",
  "Ett extra tangentbord": "Fazladan bir klavye",
  "Ett falurött hus på landet med ladugård, hönsgård och hagar fulla av djur. Bli bonde!": "Köyde kırmızı bir ev: ahır, kümes ve hayvan dolu çayırlar. Çiftçi ol!",
  "Ett fjäderspö kostar 20 kr – katterna blir tokiga i det!": "Tüylü oyuncak 20 TL – kediler ona deli oluyor!",
  "Ett flygplan": "Bir uçak",
  "Ett gammalt landshövdingehus – stenvåning nertill och två våningar trä ovanpå. Här bor andra.": "Eski bir mahalle evi – altı taş, üstü iki kat ahşap. Burada başkaları oturuyor.",
  "Ett gott val!": "İyi seçim!",
  "Ett grönt hus med blå dörr. Här bor andra.": "Mavi kapılı yeşil bir ev. Burada başkaları oturuyor.",
  "Ett gult hus med studsmatta i trädgården. Här bor andra.": "Bahçesinde trambolin olan sarı bir ev. Burada başkaları oturuyor.",
  "Ett gult hus med vita knutar. Här bor andra.": "Beyaz kenarlı sarı bir ev. Burada başkaları oturuyor.",
