  "Ett hus med en liten trädgård bakom. Här bor andra.": "Arkasında küçük bir bahçesi olan ev. Burada başkaları oturuyor.",
  "Ett hus vid kajen med båtar utanför. Här bor andra.": "Önünde tekneler duran, rıhtımda bir ev. Burada başkaları oturuyor.",
