  "Ett landshövdingehus med blomlådor i varje fönster. Här bor andra.": "Her penceresinde çiçek saksıları olan eski bir ev. Burada başkaları oturuyor.",
  "Ett landshövdingehus med cyklar på gården. Här bor andra.": "Avlusunda bisikletler duran eski bir ev. Burada başkaları oturuyor.",
  "Ett litet lok i trä – precis som det på lekmattan.": "Küçük bir ahşap lokomotif – oyun halısındakinin tıpkısı.",
  "Ett pass tar 4 timmar. Chefen betalar direkt efter passet.": "Bir vardiya 4 saat sürer. Patron vardiya bitince hemen öder.",
  "Ett pass tar tio energi. Trött? Ät något eller sov först, annars blir lyften sluddriga.": "Bir antrenman on enerji alır. Yorgun musun? Önce bir şey ye ya da uyu, yoksa kaldırışlar sallanır.",
  "Ett rosa hus med hängmatta. Familjen Rosén har garageloppis på uppfarten.": "Hamaklı pembe bir ev. Gül Ailesi garaj yolunda garaj satışı yapıyor.",
  "Ett rosa hus med hängmatta. Här bor andra.": "Hamaklı pembe bir ev. Burada başkaları oturuyor.",
  "Ett rum och kök på sjunde våningen i Betongvägen 1. Hissen går ibland.": "Beton Caddesi 1'de yedinci katta bir oda ve mutfak. Asansör bazen çalışıyor.",
  "Ett rött hus med äppelträd. Barnen Berg säljer lemonad vid grinden.": "Elma ağaçlı kırmızı bir ev. Kaya çocukları bahçe kapısında limonata satıyor.",
  "Ett rött hus med äppelträd. Här bor andra.": "Elma ağaçlı kırmızı bir ev. Burada başkaları oturuyor.",
  "Ett rött trähus med en katt i fönstret. Här bor andra.": "Penceresinde kedi oturan kırmızı ahşap bir ev. Burada başkaları oturuyor.",
  "Ett sjunde rum i Dockskåpet: tronsalen med tron, kristallkrona, rustning, fontän, himmelssäng, facklor och en drake – för alltid.": "Bebek Evi'nde yedinci oda: taht salonu; taht, kristal avize, zırh, fıskiye, cibinlikli yatak, meşaleler ve bir ejderha – sonsuza dek.",
  "Ett sjätte rum i Dockskåpet: husets baksida med gräsmatta, pool, gunga, studsmatta, grill, äppelträd och mer – för alltid.": "Bebek Evi'nde altıncı oda: evin çimenli arka bahçesi, havuz, salıncak, trambolin, mangal, elma ağacı ve daha fazlası – sonsuza dek.",
  "Ett skohorn – så glider hälen i utan att trampa ner skon. 🥄": "Ayakkabı çekeceği – topuk kayarak girer, arka ezilmez. 🥄",
