  "Välj": "Seç",
  "Välj din avatar eller skapa en ny.": "Avatarını seç ya da yeni bir tane yap.",
  "Välj en bok. Att läsa ut den tar en timme och ger en utbildningspoäng första gången.": "Bir kitap seç. Bitirmek bir saat sürer ve ilk seferinde bir eğitim puanı verir.",
  "Välj en fröpåse. Vattna bädden varje dag – två dagar utan vatten och plantorna vissnar. Skörden hamnar i skafferiet.": "Bir tohum paketi seç. Tarhı her gün sula – iki gün susuz kalırsa fideler solar. Hasat kilere gider.",
  "Välj en häst.": "Bir at seç.",
  "Välj en låt – den går hemma tills du stänger av eller lägger dig. Alla låtar i Pixelstaden finns här.": "Bir şarkı seç – kapatana ya da yatana kadar evde çalar. Pixelkent'teki tüm şarkılar burada.",
  "Välj en möbel först": "Önce bir mobilya seç",
  "Välj en ny frisyr eller färg först.": "Önce yeni bir saç modeli ya da renk seç.",
  "Välj en ny frisyr eller hårfärg – förhandsbilden visar hur det blir på dig.": "Yeni bir saç modeli ya da renk seç – önizleme sende nasıl duracağını gösterir.",
  "Välj ett belopp.": "Bir miktar seç.",
  "Välj ett märke": "Bir arma seç",
  "Välj ett ställe på kartan.": "Haritadan bir yer seç.",
  "Välj färg – en ballong kostar {0}. Den följer med dig på tivolit hela dagen!": "Renk seç – bir balon {0}. Bütün gün lunaparkta seninle gelir!",
  "Välj hur högt du siktar i varje mål. Du har klarat livet i Pixelstaden när alla fyra är nådda samtidigt.": "Her hedefte ne kadar yükseği istediğini seç. Dördüne aynı anda ulaşınca Pixelkent'te hayatı başardın demektir.",
  "Välj hur mycket du vill sätta in.": "Ne kadar yatıracağını seç.",
  "Välj hur mycket du vill ta ut.": "Ne kadar çekeceğini seç.",
  "Välj kana. Trapporna upp är branta – håll i räcket.": "Kaydırağı seç. Merdivenler dik – tırabzanı tut.",
  "Välj någon i laget – eller skriv ett eget förnamn och nummer.": "Takımdan birini seç – ya da kendi adını ve numaranı yaz.",
  "Välj något från menyn först!": "Önce menüden bir şey seç!",
  "Välj något i butiken så slår jag in det!": "Mağazadan bir şey seç, hesabını keseyim!",
  "Välkommen fram!": "Hoş geldin!",
  "Välkommen in! Värm upp lite först så går lyften lättare.": "Hoş geldin! Önce biraz ısın, kaldırışlar daha kolay olur.",
  "Välkommen in! ✨": "Hoş geldin! ✨",
  "Välkommen ombord! Vad får det lov att vara?": "Gemiye hoş geldin! Ne alırsın?",
  "Välkommen till BLIXT!": "ŞİMŞEK'e hoş geldin!",
  "Välkommen till Biblioteket! Ta en bok från hyllan och sätt dig vid ett bord. Varje utläst bok ger en utbildningspoäng.": "Kütüphane'ye hoş geldin! Raftan bir kitap al ve bir masaya otur. Bitirdiğin her kitap bir eğitim puanı verir.",
  "Välkommen till Bio Pixel!": "Sinema Pixel'e hoş geldin!",
  "Välkommen till Gamla stan! Huset bakom mig är från 1699 – titta på årtalet i gaveln.": "Eski Şehir'e hoş geldin! Arkamdaki ev 1699'dan kalma – çatıdaki yıla bak.",
  "Välkommen till Klipp & Klo! Har du ett husdjur så gör vi det jättefint här. ✂️": "Makas & Pençe'ye hoş geldin! Bir hayvanın varsa burada onu çok güzel yaparız. ✂️",
  "Välkommen till Klipp & Klo! ✂️ Klicka på trimbordet så fixar vi ditt djur.": "Makas & Pençe'ye hoş geldin! ✂️ Bakım masasına tıkla, hayvanını güzelleştirelim.",
  "Välkommen till Kurr! ☕ Fika vid disken – och klappa gärna katterna, de älskar det.": "Mırmır'a hoş geldin! ☕ Tezgâhtan çayını al – kedileri de sev, buna bayılırlar.",
  "Välkommen till Museet! Titta på föremålen – skyltarna berättar. När du sett tre stycken får du ta quizet hos mig.": "Müzeye hoş geldin! Eserlere bak – tabelalar anlatır. Üç tanesine baktıktan sonra bende yarışmaya katılabilirsin.",
  "Välkommen till Pixel Gym! Hantlarna och boxsäcken ger STYRKA, gruppasset KONDITION och dansgolvet RYTM.": "Pixel Gym'e hoş geldin! Dambıllar ve kum torbası GÜÇ, grup dersi KONDİSYON, dans pisti RİTİM verir.",
  "Välkommen till Pixelbanken!": "Pixelbank'a hoş geldin!",
  "Välkommen till frisören! Sätt dig i en ledig stol, så fixar vi håret. 💇": "Kuaföre hoş geldin! Boş bir koltuğa otur, saçını yapalım. 💇",
  "Välkommen till kassan.": "Gişeye hoş geldin.",
  "Välkommen till utställningen! Anmäl ditt djur här vid disken – det kostar 100 kr.": "Sergiye hoş geldin! Hayvanını burada tezgâhta kaydet – 100 TL.",
  "Välkommen till {0}! Första föreläsningen är i Aula 1 – sätt dig i en ledig bänk.": "{0} bölümüne hoş geldin! İlk ders Amfi 1'de – boş bir sıraya otur.",
  "Välkommen tillbaka!": "Yine bekleriz!",
  "Välkommen tillbaka! Allt rullar som det ska? 🔧": "Tekrar hoş geldin! Her şey yolunda gidiyor mu? 🔧",
  "Välkommen upp! ⚽ Laget står där borta – klicka på en spelare så provar du matchstället.": "Hoş geldin! ⚽ Takım şurada – bir oyuncuya tıkla, formayı dene.",
  "Välkommen!": "Hoş geldin!",
  "Välkommen! Ditt sparkonto växer med {0} % i veckan.": "Hoş geldin! Birikim hesabın haftada %{0} büyür.",
  "Välkommen! Entrén kostar <b>{0}</b> och gäller hela dagen. Lejonen, elefanterna, girafferna, pingvinerna, klappzoo och ponnyridningen väntar där inne.": "Hoş geldin! Giriş <b>{0}</b> ve bütün gün geçerli. Aslanlar, filler, zürafalar, penguenler, mini zoo ve midilli turu içeride seni bekliyor.",
  "Välkommen! Något nytt i dag?": "Hoş geldin! Bugün yeni bir şey mi?",
  "Välkommen! Ska vi prata sparande?": "Hoş geldin! Birikim hakkında konuşalım mı?",
  "Välkommen! Tentorna skrivs vid tentabordet, lånen här.": "Hoş geldin! Sınavlar sınav masasında, ödünç kitaplar burada.",
  "Välkommen! Vad blir det?": "Hoş geldin! Ne olsun?",
