  "🗂️ Kortkatalogen: en lapp för varje bok i huset, sorterade för hand. Porträttet är grundaren, Hedvig Bok.": "🗂️ Kart kataloğu: binadaki her kitap için bir kart, elle sıralanmış. Portredeki kişi kurucu, Hediye Kitap.",
